import type { Register } from 'claude-code'

const PREFIX = 'checkpoint:'

export const register: Register = on => {
  // Files edited during the current turn; the module's own variable, reset each turn.
  let edited = new Set<string>()

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'rollback',
      description: 'Undo the last checkpoint commit',
    })

    return next(e)
  })

  for (const tool of ['Edit', 'Write'] as const) {
    on('tool.call', { tool }, async ($, e, next) => {
      const ran = await next(e)
      if (ran.deny === undefined && ran.isError !== true) edited.add(e.file_path)

      return ran
    })
  }

  on('turn.complete', async ($, e, next) => {
    const files = [...edited]
    edited = new Set()
    const done = await next(e)
    if (files.length === 0) return done

    const add = await $.process.run(['git', 'add', '--', ...files])
    if (add.exitCode !== 0) {
      $.ui.toast(`checkpoint failed: ${add.stderr.trim().slice(0, 80)}`)
      return done
    }

    const names = files.map(f => f.split('/').pop()).join(', ')
    const commit = await $.process.run([
      'git', 'commit', '-m', `${PREFIX} ${names}`, '--only', '--', ...files,
    ])
    if (commit.exitCode !== 0) {
      // Nothing to commit (edits left the files unchanged) is not worth a toast.
      if (!/nothing (added )?to commit|no changes added/.test(commit.stdout + commit.stderr)) {
        $.ui.toast(`checkpoint failed: ${commit.stderr.trim().slice(0, 80)}`)
      }
      return done
    }

    $.ui.toast(`Checkpoint saved: ${files.length} file${files.length === 1 ? '' : 's'}`)

    return done
  })

  on('command.run', { command: 'rollback' }, async $ => {
    const log = await $.process.run(['git', 'log', '-1', '--format=%h %s'])
    if (log.exitCode !== 0) return { text: 'rollback: not a git repository with commits.' }

    const [hash, ...rest] = log.stdout.trim().split(' ')
    const subject = rest.join(' ')
    if (!subject.startsWith(PREFIX)) {
      return { text: `rollback: last commit (${hash}) is not a checkpoint; nothing undone.` }
    }

    const status = await $.process.run(['git', 'status', '--porcelain', '--untracked-files=no'])
    if (status.stdout.trim() !== '') {
      return { text: 'rollback: uncommitted changes would be lost; commit or stash them first.' }
    }

    const reset = await $.process.run(['git', 'reset', '--hard', 'HEAD~1'])
    if (reset.exitCode !== 0) return { text: `rollback failed: ${reset.stderr.trim()}` }

    $.ui.toast('Rolled back last checkpoint')

    return { text: `Rolled back ${hash} (${subject}).` }
  })
}

